3. Laboratorio: calcula un índice h


Laboratorio · se ejecuta en tu navegador

Escribe las citas de cada trabajo de un perfil (separadas por comas). El laboratorio las ordena, calcula el índice h y lo compara con la media y la mediana.

texto = window.Lab.texto
viewof citas_txt = texto("Citas por trabajo", {value: "120, 45, 30, 22, 15, 12, 9, 8, 6, 5, 3, 2, 1, 0, 0", submit: "Calcular"})
















{
  const c = citas_txt.split(/[,;\s]+/).map(Number).filter(Number.isFinite).sort((a, b) =&gt; b - a);
  if (!c.length) return html`&lt;p role="status"&gt;Escribe al menos un número.&lt;/p&gt;`;
  let h = 0; c.forEach((v, i) =&gt; { if (v &gt;= i + 1) h = i + 1; });
  const media = c.reduce((a, b) =&gt; a + b, 0) / c.length, med = c.length % 2 ? c[(c.length - 1) / 2] : (c[c.length / 2 - 1] + c[c.length / 2]) / 2;
  const max = Math.max(...c, 1), W = 520, H = 200, bw = Math.max(4, (W - 40) / c.length - 2);
  const barras = c.map((v, i) =&gt; `&lt;rect x="${30 + i * (bw + 2)}" y="${H - 20 - (H - 40) * v / max}" width="${bw}" height="${(H - 40) * v / max}" fill="${i &lt; h ? "#2a78d6" : "#a3a29e"}"/&gt;`).join("");
  const fmt = x =&gt; x.toLocaleString("es-ES", {maximumFractionDigits: 1});
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;p&gt;&lt;strong&gt;Índice h = ${h}&lt;/strong&gt; · ${c.length} trabajos · ${fmt(c.reduce((a, b) =&gt; a + b, 0))} citas · media ${fmt(media)} · mediana ${fmt(med)}&lt;/p&gt;
   &lt;svg viewBox="0 0 ${W} ${H}" width="100%" style="max-width:${W}px" role="img" aria-label="Citas por trabajo ordenadas de mayor a menor; en azul los ${h} trabajos del núcleo h"&gt;
   &lt;line x1="28" y1="${H - 20}" x2="${W - 5}" y2="${H - 20}" stroke="currentColor" stroke-opacity=".4"/&gt;${barras}&lt;/svg&gt;
   &lt;p class="small"&gt;En azul, el «núcleo h». Prueba a cambiar 120 por 1200: el índice h no se mueve, pero la media se dispara.&lt;/p&gt;`;
  return d;
}

4. Laboratorio: ¿cuánto te fías de un resultado significativo?


Laboratorio · cálculo en tu navegador

Imagina 1000 hipótesis puestas a prueba en un campo. Ajusta la proporción de hipótesis verdaderas, la potencia, el umbral y el sesgo, y mira cuántos resultados significativos son verdaderos.

rango = window.Lab.rango
viewof p_prev = rango("Hipótesis verdaderas (de cada 100 que se prueban)", [1, 50], {step: 1, value: 10})
viewof potencia = rango("Potencia (%)", [5, 99], {step: 1, value: 35})
viewof alfa = rango("Umbral α", [0.001, 0.1], {step: 0.001, value: 0.05, formato: x =&gt; x.toFixed(3).replace(".", ",")})
viewof sesgo = rango("Sesgo u (proporción de nulos convertidos en positivos)", [0, 0.5], {step: 0.05, value: 0, formato: x =&gt; x.toFixed(2).replace(".", ",")})





































{
  const N = 1000, verd = N * p_prev / 100, fals = N - verd, pw = potencia / 100;
  const vp = verd * (pw + sesgo * (1 - pw)), fp = fals * (alfa + sesgo * (1 - alfa));
  const vpp = vp / (vp + fp);
  const fmt = x =&gt; Math.round(x).toLocaleString("es-ES");
  const W = 520, esc = (W - 20) / N;
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;p&gt;De ${fmt(N)} hipótesis, ${fmt(verd)} son verdaderas. Salen significativas &lt;strong&gt;${fmt(vp)}&lt;/strong&gt; verdaderas y &lt;strong&gt;${fmt(fp)}&lt;/strong&gt; falsas.&lt;/p&gt;
   &lt;p style="font-size:1.2rem"&gt;Valor predictivo positivo: &lt;strong&gt;${(100 * vpp).toFixed(0)} %&lt;/strong&gt; &lt;span class="${vpp &gt;= .8 ? "lab-bien" : vpp &gt;= .5 ? "lab-medio" : "lab-mal"}" style="font-weight:600"&gt;${vpp &gt;= .8 ? "· bastante fiable" : vpp &gt;= .5 ? "· dudoso" : "· es más probable que sea falso"}&lt;/span&gt;&lt;/p&gt;
   &lt;svg viewBox="0 0 ${W} 46" width="100%" style="max-width:${W}px" role="img" aria-label="Resultados significativos: ${fmt(vp)} verdaderos y ${fmt(fp)} falsos"&gt;
   &lt;rect x="10" y="8" width="${(W - 20) * vp / Math.max(vp + fp, 1)}" height="24" fill="#1baf7a"/&gt;
   &lt;rect x="${10 + (W - 20) * vp / Math.max(vp + fp, 1)}" y="8" width="${(W - 20) * fp / Math.max(vp + fp, 1)}" height="24" fill="#eb6834"/&gt;
   &lt;text x="10" y="44" font-size="11" fill="currentColor"&gt;verdaderos&lt;/text&gt;&lt;text x="${W - 10}" y="44" font-size="11" text-anchor="end" fill="currentColor"&gt;falsos&lt;/text&gt;&lt;/svg&gt;
   &lt;p class="small"&gt;Modelo de Ioannidis (2005). Prueba: 10 de cada 100 hipótesis verdaderas, potencia 20 % y un poco de sesgo (0,1). Después sube la potencia al 80 % y baja α a 0,005.&lt;/p&gt;`;
  return d;
}

3. Laboratorio: fabrica un falso positivo sin hacer trampa


Laboratorio · simulación en tu navegador

Simulamos 2000 estudios en los que no hay ningún efecto real (dos grupos idénticos). Con un análisis honesto y único, alrededor del 5 % sale significativo por azar. Activa las decisiones flexibles y mira cómo sube la tasa de falsos positivos.

casilla = window.Lab.casilla
rango = window.Lab.rango
viewof dos_vd = casilla("Medir dos variables dependientes correlacionadas y quedarse con la que salga", {value: false})
viewof parada = casilla("Parada opcional: si no sale, añadir 10 personas por grupo (hasta dos veces)", {value: false})
viewof atipicos = casilla("Probar también el análisis excluyendo los valores extremos", {value: false})
viewof subgrupo = casilla("Probar también solo en un subgrupo (por ejemplo, solo mujeres)", {value: false})
viewof n_ini = rango("Personas por grupo al inicio", [10, 100], {step: 5, value: 20})



















































{
  let s = 7; const u = () =&gt; (s = (s * 16807) % 2147483647) / 2147483647;
  const norm = () =&gt; Math.sqrt(-2 * Math.log(u())) * Math.cos(2 * Math.PI * u());
  const Phi = z =&gt; { const t = 1 / (1 + 0.2316419 * Math.abs(z)), d = 0.3989423 * Math.exp(-z * z / 2);
    const p = d * t * (0.3193815 + t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274)))); return z &gt; 0 ? 1 - p : p; };
  const pval = (a, b) =&gt; { const m = x =&gt; x.reduce((p, q) =&gt; p + q, 0) / x.length;
    const v = x =&gt; { const mm = m(x); return x.reduce((p, q) =&gt; p + (q - mm) ** 2, 0) / (x.length - 1); };
    const z = (m(a) - m(b)) / Math.sqrt(v(a) / a.length + v(b) / b.length); return 2 * (1 - Phi(Math.abs(z))); };
  const persona = () =&gt; { const y1 = norm(), y2 = 0.5 * y1 + Math.sqrt(0.75) * norm(); return {y1, y2, sexo: u() &lt; 0.5}; };
  const S = 2000; let fp = 0;
  for (let k = 0; k &lt; S; k++) {
    let A = Array.from({length: n_ini}, persona), B = Array.from({length: n_ini}, persona), sig = false;
    for (let ronda = 0; ronda &lt; (parada ? 3 : 1) && !sig; ronda++) {
      if (ronda &gt; 0) { A = A.concat(Array.from({length: 10}, persona)); B = B.concat(Array.from({length: 10}, persona)); }
      const vds = dos_vd ? ["y1", "y2"] : ["y1"];
      for (const vd of vds) {
        const conj = [[A, B]];
        if (subgrupo) conj.push([A.filter(p =&gt; p.sexo), B.filter(p =&gt; p.sexo)]);
        for (const [a0, b0] of conj) {
          const a = a0.map(p =&gt; p[vd]), b = b0.map(p =&gt; p[vd]);
          if (a.length &gt; 2 && b.length &gt; 2 && pval(a, b) &lt; 0.05) sig = true;
          if (atipicos) { const f = x =&gt; x.filter(v =&gt; Math.abs(v) &lt; 2); const af = f(a), bf = f(b); if (af.length &gt; 2 && bf.length &gt; 2 && pval(af, bf) &lt; 0.05) sig = true; }
        }
      }
    }
    if (sig) fp++;
  }
  const t = fp / S;
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;p style="font-size:1.2rem"&gt;Tasa de falsos positivos: &lt;strong&gt;${(100 * t).toFixed(1).replace(".", ",")} %&lt;/strong&gt; &lt;span class="${t &lt;= .06 ? "lab-bien" : t &lt;= .15 ? "lab-medio" : "lab-mal"}" style="font-weight:600"&gt;${t &lt;= .06 ? "· lo nominal" : "· inflada"}&lt;/span&gt;&lt;/p&gt;
   &lt;svg viewBox="0 0 520 40" width="100%" style="max-width:520px" role="img" aria-label="Barra de la tasa de falsos positivos"&gt;&lt;rect x="10" y="8" width="500" height="20" rx="4" fill="#d9d8d4"/&gt;&lt;rect x="10" y="8" width="${500 * t}" height="20" rx="4" fill="#eb6834"/&gt;&lt;line x1="${10 + 500 * .05}" x2="${10 + 500 * .05}" y1="2" y2="34" stroke="currentColor" stroke-width="2"/&gt;&lt;text x="${14 + 500 * .05}" y="38" font-size="10" fill="currentColor"&gt;5 % nominal&lt;/text&gt;&lt;/svg&gt;
   &lt;p class="small"&gt;2000 estudios simulados sin efecto real; prueba aproximada con la distribución normal. Activa las cuatro decisiones a la vez.&lt;/p&gt;`;
  return d;
}
